import { createParser } from './parse.ts';
/**
 * A TransformStream that ingests a stream of strings and produces a stream of `EventSourceMessage`.
 *
 * @example Basic usage
 * ```
 * const eventStream =
 *   response.body
 *     .pipeThrough(new TextDecoderStream())
 *     .pipeThrough(new EventSourceParserStream())
 * ```
 *
 * @example Terminate stream on parsing errors
 * ```
 * const eventStream =
 *  response.body
 *   .pipeThrough(new TextDecoderStream())
 *   .pipeThrough(new EventSourceParserStream({terminateOnError: true}))
 * ```
 *
 * @public
 */
export class EventSourceParserStream extends TransformStream {
    constructor({ onError, onRetry, onComment } = {}) {
        let parser;
        super({
            start(controller) {
                parser = createParser({
                    onEvent: (event) => {
                        controller.enqueue(event);
                    },
                    onError(error) {
                        if (onError === 'terminate') {
                            controller.error(error);
                        }
                        else if (typeof onError === 'function') {
                            onError(error);
                        }
                        // Ignore by default
                    },
                    onRetry,
                    onComment,
                });
            },
            transform(chunk) {
                parser.feed(chunk);
            },
        });
    }
}
export { ParseError } from './errors.ts';
